import os, json
P="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
B=os.path.join(P,".lake/build/lib/lean")
d=json.load(open("/tmp/reach.json")); paths=d["paths"]; unrooted=set(d["unrooted"])
edges={}
for m,p in paths.items():
    ims=[]
    for line in open(p,encoding='utf-8',errors='replace'):
        s=line.strip()
        if s.startswith('import '):
            t=s.split()[1]
            if t.startswith('AlgebraicJacobian.'): ims.append(t)
    edges[m]=ims
def ol(m): return os.path.join(B,"/".join(m.split("."))+".olean")
import functools
memo={}
def dirty(m, stack=()):
    if m in memo: return memo[m]
    if m in stack: return False
    o=ol(m)
    if not os.path.exists(o): memo[m]=("no-olean",); return memo[m]
    if os.path.getmtime(o) < os.path.getmtime(paths[m]): memo[m]=("src-newer",); return memo[m]
    for dep in edges.get(m,[]):
        if dep not in paths: continue
        r=dirty(dep, stack+(m,))
        if r: memo[m]=("dep:"+dep.split('.')[-1]+":"+r[0],); return memo[m]
        od=ol(dep)
        if os.path.exists(od) and os.path.getmtime(od) > os.path.getmtime(o):
            memo[m]=("dep-olean-newer:"+dep.split('.')[-1],); return memo[m]
    memo[m]=None; return None
res={m:dirty(m) for m in sorted(unrooted)}
bad={m:v for m,v in res.items() if v}
print("UNROOTED modules whose olean is absent or stale (propagated):", len(bad), "of", len(unrooted))
for m,v in sorted(bad.items()): print(f"  {m.replace('AlgebraicJacobian.',''):58s} {v[0]}")
# also check trace files
tr=sum(1 for m in unrooted if os.path.exists(os.path.join(B,"/".join(m.split("."))+".trace")))
print("unrooted with .trace:", tr)
# rooted staleness for comparison
rbad=sum(1 for m in d["reachable"] if dirty(m))
print("rooted modules dirty by same test:", rbad, "of", len(d["reachable"]))
EOF

